    $focused := false
    $anchor := 0
    $head := 0
    $dragging := false
    $clipboard := ""
    $clip_seq := 0
    $just_copied := false
    $scroll_x := 0.0
    while true {
        event := playground.next_input()
        if event.kind == 0 { <- }
        if event.kind == 77 {
            focused = false
            dragging = false
        }
        if event.kind == 72 {
            px := event.x
            py := event.y
            just_copied = false
            if px >= bounds.x && px <= bounds.x + bounds.width && py >= bounds.y && py <= bounds.y + bounds.height {
