            } else {
                focused = false
                dragging = false
            }
        } else if event.kind == 74 && dragging {
            head = hit_pos(&context,&edit_opts,&text,event.x - text_x + scroll_x) or >>
            scroll_x = compute_scroll(&context,&edit_opts,&text,head,view_w,scroll_x) or >>
        } else if event.kind == 73 {
            dragging = false
        }
        if event.kind == 78 {
            if event.key == 257 {
                focused = !focused
                just_copied = false
                if focused {
                    anchor = 0
                    head = text.len
                    scroll_x = compute_scroll(&context,&edit_opts,&text,head,view_w,scroll_x) or >>
                }
