    if key == 39 { if shift { << "\"" } << "'" }
    if key == 44 { if shift { << "<" } << "," }
    if key == 45 { if shift { << "_" } << "-" }
    if key == 46 { if shift { << ">" } << "." }
    if key == 47 { if shift { << "?" } << "/" }
    if key == 59 { if shift { << ":" } << ";" }
    if key == 61 { if shift { << "+" } << "=" }
    if key == 91 { if shift { << "{" } << "[" }
    if key == 92 { if shift { << "|" } << "\\" }
    if key == 93 { if shift { << "}" } << "]" }
    if key == 96 { if shift { << "~" } << "`" }
    if key >= 33 && key <= 126 { << string_from_byte(key) }
